import time
from collections import deque
import numpy as np

class SentinelDetector:
    def __init__(self, threshold_ms=12.0, entropy_cutoff=1.8):
        self.key_timestamps = deque(maxlen=30)
        self.threshold_ms = threshold_ms
        self.entropy_cutoff = entropy_cutoff

    def process_key_event(self, key_code):
        now = time.perf_counter() * 1000.0  # ms
        self.key_timestamps.append(now)

        if len(self.key_timestamps) >= 15:
            deltas = np.diff(list(self.key_timestamps))
            mean_interval = np.mean(deltas)
            std_dev = np.std(deltas)

            # Detect superhuman burst or zero-jitter injection
            if mean_interval < self.threshold_ms and std_dev < 2.0:
                self.trigger_mitigation(deltas, mean_interval)

    def trigger_mitigation(self, deltas, mean_speed):
        print(f"[!] HID INJECTION DETECTED: {mean_speed:.2f}ms/key avg. Isolating input!")
